let restoreCreateFocus=false;
const view = document.querySelector('#view');
const demo = { result:false, roomName:null, roomDuration:null, roomEndsAt:null, votes:{}, ideas:[{id:1,title:'Dumplings, then see where the night goes.',details:'That little place on Rua da Rosa. Good food, no big itinerary.',author:'Sofia',score:5},{id:2,title:'A film under the stars',details:'Outdoor cinema at 21:00. Bring a jumper and something to share.',author:'Miguel',score:3}] };
const button = (label,route='room') => `<a class="button" href="#${label==='Make a plan'?'signup':route}">${label} <span>↗</span></a>`;
function landing(){return `<section class="hero"><p class="eyebrow">For the group chat that never decides.</p><div class="hero-top"><h1>Good people.<br><i>One good plan.</i></h1><div class="hero-side"><p>Bring your group’s ideas together, vote on your favourites, and make a plan.</p>${button('Make a plan','dashboard')}<button class="walkthrough-link" data-action="walkthrough">See how it works ↗</button></div></div><div class="hero-bottom"><span>IDEAS → VOTES → ACTUAL PLANS</span><span>Scroll. See how a plan comes together ↓</span></div></section><div class="scene-wrap"><section class="scene" id="walkthrough" data-stage="idea" aria-label="Illustration of a group choosing between ideas"><span class="scene-label">01 / ADD AN IDEA</span><div class="scene-progress" aria-label="How a plan comes together"><span data-stage-step="idea">01 Add an idea</span><span data-stage-step="vote">02 Vote together</span><span data-stage-step="decision">03 Make the plan</span></div><span class="orbit" aria-hidden="true">↗</span><div class="board"><article class="ticket" data-stage="idea"><small>01 / SOFIA ADDS AN IDEA</small><h3>Dumplings?<br>Absolutely dumplings.</h3><div class="ticket-bottom"><span class="stamp">↗ YEA · 6</span><span>↘ NAY · 1</span></div></article><article class="ticket" data-stage="vote"><small>02 / THE GROUP VOTES</small><h3>Film under the stars.</h3><div class="ticket-bottom"><span class="stamp">↗ YEA · 4</span><span>↘ NAY · 2</span></div></article><article class="ticket" data-stage="decision"><small>03 / THE GROUP HAS DECIDED</small><h3>Meet you at 8. ↗</h3></article></div><span class="scene-caption">Turn all those<br>“maybe”s into a plan.</span></section></div><section class="steps"><p class="eyebrow">Less organising. More living.</p><h2>A room for your ideas.<br>A reason to get out.</h2><div class="step-grid"><article><b>01 / GET TOGETHER</b><h3>Open the question.</h3><p>Friday night? Your next trip? Start a room, set a deadline, and send the link.</p></article><article><b>02 / PUT IT OUT THERE</b><h3>Every idea gets a say.</h3><p>Add a suggestion. Give a yea to what you love and a nay to what you don’t.</p></article><article><b>03 / MAKE IT HAPPEN</b><h3>There’s your plan.</h3><p>When time is up, see what the group picked. The next part is yours.</p></article></div><div style="margin-top:35px">${button('Try a sample room')}</div></section>`}
function dashboard(){return `<div class="page"><div class="page-heading"><div><p class="eyebrow">Your corner of the group chat</p><h1>Hey, Alex.<br>What’s the plan?</h1><p class="muted">A few good ideas. Your favourite people. Let’s decide.</p></div><div class="actions"><button class="button secondary" data-action="join">Join with a code ↗</button><button class="button" data-action="create">Create a room ＋</button></div></div><div class="section-label"><span>IN THE WORKS</span><span>02 OPEN ROOMS</span></div><div class="rooms"><a class="room-card" href="#room"><span class="status">Voting · ends today at 20:00</span><h2>Friday night.<br>What’s the move?</h2><div class="meta"><span>6 PEOPLE / 2 IDEAS</span><span>OPEN ↗</span></div></a><a class="room-card" href="#room"><span class="status">Voting · ends tomorrow</span><h2>Somewhere<br>for the weekend.</h2><div class="meta"><span>4 PEOPLE / 5 IDEAS</span><span>OPEN ↗</span></div></a><a class="room-card" href="#room" data-result="true"><span class="status">Decided / last Saturday</span><h2>Beach day.<br>Good call.</h2><div class="meta"><span>THE GROUP PICKED COSTA</span><span>RESULT ↗</span></div></a></div><div class="room-note"><b>Plans start with a question.</b><p class="muted">You don’t need the perfect idea. Open a room and let everyone bring something to the table.</p></div></div>`}
function ideaCard(idea){const selected=demo.votes[idea.id]||0;return `<article class="idea"><div class="idea-top"><span>${idea.author.toUpperCase()}’S IDEA</span><span>${idea.id===1?'01':'02'}</span></div><h2>${escapeText(idea.title)}</h2><p>${escapeText(idea.details)}</p><div class="vote-row"><button class="vote ${selected===1?'selected':''}" data-vote="1" data-id="${idea.id}" aria-pressed="${selected===1}" ${demo.result?'disabled':''}>↗ Yea ${selected===1?'✓':''}</button><button class="vote ${selected===-1?'selected':''}" data-vote="-1" data-id="${idea.id}" aria-pressed="${selected===-1}" ${demo.result?'disabled':''}>↘ Nay ${selected===-1?'✓':''}</button><span class="vote-note">${demo.result?'Voting is closed':selected?'Your vote · tap again to remove':'What do you think?'}</span><span class="score">${idea.score+selected>0?'+':''}${idea.score+selected} net votes</span></div></article>`}
function room(){return `<div class="page"><a class="eyebrow" href="#dashboard">← All your rooms</a><div class="page-heading"><div><p class="eyebrow" style="margin-top:30px">${demo.roomName?"YOUR DEMO ROOM / 1 MEMBER":"THE FRIDAY PEOPLE / 6 MEMBERS"}</p><h1>${demo.roomName?escapeText(demo.roomName):"Friday night.<br>What’s the move?"}</h1><p class="muted">${demo.roomName?"Demo room created by Alex · Nothing is saved to a server.":"Created by Sofia · A good plan beats another “I don’t mind”."}</p></div><span class="deadline">${demo.result?'● DECIDED':demo.roomName?'● DEMO VOTING / '+escapeText(demo.roomDuration)+' / ENDS '+new Date(demo.roomEndsAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'● VOTING OPEN / ENDS TODAY AT 20:00'}</span></div><div class="room-layout"><section>${demo.result?`<div class="result"><p class="eyebrow">The group has decided ↗</p><h2>${escapeText([...demo.ideas].sort((a,b)=>(b.score+(demo.votes[b.id]||0))-(a.score+(demo.votes[a.id]||0)))[0]?.title||'Add an idea to begin.')}</h2><p>Sample result preview · Nothing has been closed on a server.</p></div>`:`<form class="composer"><label for="idea-title">Bring an idea to the table.</label><input id="idea-title" name="title" placeholder="What would you love to do?" maxlength="100" required><textarea name="details" aria-label="Idea details" placeholder="The place, the time, the little details… (optional)" maxlength="500" rows="2"></textarea><div class="composer-bottom"><small>Everyone can suggest. Everyone can vote.</small><button class="button" type="submit">Post idea ↗</button></div></form>`}<div class="section-label"><span>ON THE TABLE / ${demo.ideas.length} IDEAS</span><span>YEA = +1 · NAY = −1</span></div>${demo.ideas.map(ideaCard).join('')}</section><aside class="side"><section><h3>Good company.</h3><div class="people">${demo.roomName?"<span>AL</span>":"<span>SO</span><span>MI</span><span>AL</span><span>JO</span><span>+2</span>"}</div><p>${demo.roomName?"You’re hosting this demo as Alex.":"Sofia is hosting.<br>You’re here as Alex."}</p></section><section><h3>Room for your people.</h3><p>Share the code. Bring the group into the decision.</p><div class="code">FRIDAY</div><button class="button secondary" data-action="copy">Copy invite link ↗</button></section><section><p class="eyebrow">Prototype controls</p><p>Explore the voting and result states. These sample interactions stay in this tab only.</p><button class="button secondary" data-action="result">${demo.result?'Reopen sample voting':'Preview final result'} ↗</button></section></aside></div></div>`}
function legal(){return `<div class="page"><p class="eyebrow">Still part of the conversation</p><h1>Your plans.<br>Your privacy.</h1><p class="muted">Privacy notice · Design preview</p><div class="legal-layout"><aside class="legal-menu"><a href="#legal" aria-current="page">Privacy notice ↗</a><a href="#legal" data-action="terms">Terms of service ↗</a><a href="#dashboard">Back to your rooms ↗</a></aside><article class="legal-copy"><div class="notice"><strong>Layout preview, not a published policy.</strong> The text below demonstrates the reading layout. Existing legal drafts, publisher details, and policy decisions must be reviewed before release.</div><h2>A place to make plans together.</h2><p>Understanding how your information is handled should feel as straightforward as using the app. This space is designed for a complete, readable privacy notice, within the same navigation and visual identity as your rooms.</p><h2>What you share</h2><p>The final notice will explain account information, room ideas, comments and uploaded images, including how each is used to provide the service.</p><h2>Your choices</h2><p>Account controls, deletion, retention periods and contact details will be documented here. This prototype does not establish or change any policy.</p><h2>A question about your data?</h2><p>A verified service contact belongs here before launch. You can return to your rooms using the same navigation above.</p></article></div></div>`}
function escapeText(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function auth(signup=false){return `<section class="auth-page"><div class="auth-story"><p class="eyebrow">${signup?'A little less “whatever”.':'Your people. Your plans.'}</p><h1>${signup?'Your next<br>good plan<br><em>starts here.</em>':'Good to<br>have you<br><em>back.</em>'}</h1><p class="auth-intro">${signup?'Bring your people together.<br>Put every idea on the table.<br>Find your next “let’s do it”.':'The ideas are on the table.<br>Come back into the conversation.'}</p><div class="auth-graphic" aria-hidden="true"><div class="auth-mini"><small>THE GROUP HAS DECIDED</small><strong>Less “you choose”.<br>More “see you there”.</strong><span>↗ YEA, LET’S GO.</span></div><div class="auth-arrow">↗</div></div><p class="auth-footnote">GOOD PEOPLE. ONE GOOD PLAN.</p></div><div class="auth-form-panel"><div class="auth-form-top"><span class="eyebrow">${signup?'01 / MAKE YOURSELF AT HOME':'01 / COME ON IN'}</span><a href="#landing">Back to the idea ↗</a></div><div class="auth-form-wrap"><h2>${signup?'Join the conversation.':'Sign in.'}</h2><p class="muted">${signup?'A place for your people to make up their minds.':'Your rooms are right where you left them.'}</p><div class="auth-demo-note">Design preview · Use made-up details. This form does not create an account or send your details anywhere.</div><form id="auth-demo-form">${signup?'<div class="auth-field"><label for="auth-name">What should we call you?</label><input id="auth-name" name="name" autocomplete="name" placeholder="Your name" maxlength="40" required></div>':''}<div class="auth-field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required></div><div class="auth-field"><label for="auth-password">Password</label><div class="password-field"><input id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="10"':''} placeholder="${signup?'At least 10 characters':'Your password'}" required><button type="button" class="password-toggle" aria-controls="auth-password" aria-pressed="false">Show</button></div>${signup?'<small>Make it at least 10 characters.</small>':''}</div>${signup?'<label class="auth-confirm"><input type="checkbox" name="adult" required><span>I confirm that I am 18 or older.</span></label>':''}<button class="button auth-submit" type="submit">${signup?'Preview creating an account':'Preview signing in'} <span>↗</span></button><p class="auth-status" role="status" tabindex="-1"></p></form><p class="auth-switch">${signup?'Already part of the group? <a href="#login">Sign in ↗</a>':'New around here? <a href="#signup">Create an account ↗</a>'}</p><p class="auth-legal">Read the <a href="#legal">privacy layout</a> and <a href="#legal">terms layout</a>. This preview does not submit an agreement.</p></div></div></section>`}
function create(){return dashboard()+`<dialog class="create-dialog" aria-labelledby="create-heading"><div class="modal-heading"><div><p class="eyebrow">One question. Everyone’s ideas.</p><h2 id="create-heading">Create a room.</h2></div><button class="modal-close" type="button" data-action="close-create" aria-label="Close create room">✕</button></div><form id="create-demo-form" class="create-form"><div class="auth-demo-note">Design preview · This creates a temporary room in this tab. Nothing is sent to a server.</div><div class="create-field"><label for="create-question">What are we deciding?</label><input id="create-question" name="name" autofocus placeholder="Friday night. What’s the move?" maxlength="70" required><small>Give your room a question. Up to 70 characters.</small></div><div class="create-field create-duration"><label for="create-duration">How long should voting last?</label><select id="create-duration" name="duration"><option value="15">15 minutes · quick pick</option><option value="30" selected>30 minutes · just right</option><option value="60">1 hour · take your time</option><option value="180">3 hours</option><option value="1440">24 hours · decide tomorrow</option><option value="custom">Custom date &amp; time</option></select></div><div class="create-field" id="create-custom-end" hidden><label for="create-ends">Voting ends</label><input id="create-ends" name="endsAt" type="datetime-local" disabled><small>Choose a date and time in the future.</small></div><div class="create-field"><label for="create-image">Room image <span class="muted">(optional)</span></label><div class="image-picker"><input id="create-image" class="image-picker-input" type="file" accept="image/png,image/jpeg,image/webp" aria-describedby="image-filename"><span class="image-picker-button" aria-hidden="true">Choose an image ↗</span><span id="image-filename">PNG, JPEG or WebP</span></div><small>A local preview only. No file is uploaded.</small><img class="create-image-preview" id="create-image-preview" alt="Selected room image preview" hidden></div><div class="create-actions"><button class="button secondary" type="button" data-action="close-create">Cancel</button><button class="button" type="submit">Open demo room ↗</button></div></form></dialog>`}
function login(){return auth(false)}
function signup(){return auth(true)}
function render(){const route=location.hash.slice(1)||'landing';view.innerHTML=({landing,dashboard,room,legal,login,signup,create}[route]||landing)();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));document.title=`Yea or Nay — ${route} / V2 prototype`;document.body.classList.toggle("modal-open",route==="create");if(route==="create"){const dialog=document.querySelector(".create-dialog");dialog.showModal();dialog.addEventListener("cancel",e=>{e.preventDefault();closeCreate()});dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeCreate()}})}else if(restoreCreateFocus){document.querySelector("[data-action=create]")?.focus();restoreCreateFocus=false}prepareForms();updateScroll()}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3500)}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-vote],[data-result]');if(!target)return;if(target.dataset.result){demo.result=true;if(location.hash==='#room')render();return}if(target.dataset.vote){const id=target.dataset.id,value=Number(target.dataset.vote);demo.votes[id]=demo.votes[id]===value?0:value;const y=scrollY;render();scrollTo(0,y);return}const action=target.dataset.action;if(action==='close-create'){closeCreate();return}if(action==='result'){if(!demo.ideas.length){toast('Add an idea before previewing the result.');return}demo.result=!demo.result;render()}if(action==='copy'){try{await navigator.clipboard.writeText(location.href.split('#')[0]+'#room');toast('Sample room link copied.')}catch{toast('Sample room code: FRIDAY')}}if(action==='walkthrough'){document.querySelector('#walkthrough')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}if(action==='create'){location.hash='create';return}if(action==='join'){toast('Joining the sample room. Any code works in this design preview.');demo.result=false;location.hash='room'}if(action==='terms'){e.preventDefault();toast('Terms will use this same shared layout. This preview contains no legal policy.')}});
document.addEventListener('submit',e=>{if(!e.target.matches('.composer'))return;e.preventDefault();if(!validateForm(e.target))return;const data=new FormData(e.target);const title=String(data.get('title')).trim();if(!title)return;demo.ideas.unshift({id:Date.now(),title,details:String(data.get('details')).trim(),author:'Alex',score:0});render();toast('Sample idea added — visible only in this tab.')});
function updateScroll(){const board=document.querySelector('.board'),wrap=document.querySelector('.scene-wrap'),scene=document.querySelector('.scene');if(!board||!wrap)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const progress=reduced?1:Math.max(0,Math.min(1,(window.innerHeight*.35-wrap.getBoundingClientRect().top)/(wrap.offsetHeight*.75)));const stage=progress<.32?'idea':progress<.67?'vote':'decision';scene.dataset.stage=stage;scene.dataset.reducedMotion=String(reduced);scene.querySelector('.scene-label').textContent={idea:'01 / SOFIA ADDS AN IDEA',vote:'02 / EVERYONE HAS A SAY',decision:'03 / THE GROUP HAS DECIDED'}[stage];scene.querySelectorAll('[data-stage-step]').forEach(el=>{el.dataset.active=String(el.dataset.stageStep===stage)});board.style.transform=reduced?'none':'translateY('+(-progress*32)+'px) rotate('+(-7+progress*7)+'deg) scale('+(1+progress*.17)+')';}
window.addEventListener('scroll',updateScroll,{passive:true});window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
document.addEventListener('click',e=>{const toggle=e.target.closest('.password-toggle');if(!toggle)return;const field=document.querySelector('#auth-password');const reveal=field.type==='password';field.type=reveal?'text':'password';toggle.textContent=reveal?'Hide':'Show';toggle.setAttribute('aria-pressed',String(reveal))});
document.addEventListener('submit',e=>{if(e.target.id!=='auth-demo-form')return;e.preventDefault();const form=e.target;if(!validateForm(form))return;form.reset();const field=form.querySelector('#auth-password');field.type='password';const toggle=form.querySelector('.password-toggle');toggle.textContent='Show';toggle.setAttribute('aria-pressed','false');const status=form.querySelector('.auth-status');status.textContent='Preview complete. Your details were cleared. No account was created and nothing was sent or saved.';status.focus()});
document.addEventListener('change',e=>{if(e.target.id!=='create-duration')return;const custom=e.target.value==='custom';const field=document.querySelector('#create-ends');document.querySelector('#create-custom-end').hidden=!custom;field.disabled=!custom;field.required=custom;field.setCustomValidity('');if(custom){const future=new Date(Date.now()+60000);field.min=new Date(future.getTime()-future.getTimezoneOffset()*60000).toISOString().slice(0,16)}});
document.addEventListener('input',e=>{if(e.target.id==='create-question')e.target.setCustomValidity('');if(e.target.id==='create-ends')e.target.setCustomValidity('')});
document.addEventListener('submit',e=>{if(e.target.id!=='create-demo-form')return;e.preventDefault();const form=e.target;if(!validateForm(form))return;const question=form.elements.name;const title=question.value.trim();if(!title){question.setCustomValidity('Give your room a question.');showFieldError(question,"Give your room a question.");question.focus();return}question.setCustomValidity('');const duration=form.elements.duration.value;const custom=duration==='custom';const ends=custom?new Date(form.elements.endsAt.value).getTime():Date.now()+Number(duration)*60000;if(!Number.isFinite(ends)||ends<=Date.now()){form.elements.endsAt.setCustomValidity('Choose a date and time in the future.');showFieldError(form.elements.endsAt,"Choose a date and time in the future.");form.elements.endsAt.focus();return}demo.roomName=title;demo.roomDuration=custom?'Custom deadline':({15:'15 minutes',30:'30 minutes',60:'1 hour',180:'3 hours',1440:'24 hours'})[duration];demo.roomEndsAt=ends;demo.result=false;demo.ideas=[];demo.votes={};location.hash='room';toast('Demo room opened. Add your first idea — nothing is saved to a server.')});
let imagePreviewUrl;
document.addEventListener('change',e=>{if(e.target.id!=='create-image')return;const file=e.target.files[0];document.querySelector("#image-filename").textContent=file?file.name:"PNG, JPEG or WebP";const preview=document.querySelector('#create-image-preview');if(imagePreviewUrl)URL.revokeObjectURL(imagePreviewUrl);preview.hidden=true;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){e.target.value='';toast('Choose a PNG, JPEG or WebP image.');return}imagePreviewUrl=URL.createObjectURL(file);preview.src=imagePreviewUrl;preview.hidden=false});


function closeCreate(){if(imagePreviewUrl){URL.revokeObjectURL(imagePreviewUrl);imagePreviewUrl=null}restoreCreateFocus=true;location.hash="dashboard"}

function prepareForms(){document.querySelectorAll('form').forEach(form=>{form.noValidate=true;form.querySelectorAll('input,textarea,select').forEach(field=>{if(field.type==='file'||field.type==='hidden')return;const id=field.id||('field-'+field.name);field.id=id;const error=document.createElement('p');error.id=id+'-error';error.className='field-error';error.hidden=true;error.setAttribute('aria-live','polite');const container=field.closest('.password-field')||field.closest('.auth-confirm')||field;container.insertAdjacentElement('afterend',error);const described=field.getAttribute('aria-describedby');field.setAttribute('aria-describedby',[described,error.id].filter(Boolean).join(' '))})})}
function fieldError(field){if(field.disabled)return '';if(field.type==='checkbox')return field.required&&!field.checked?'Confirm that you are 18 or older to continue.':'';const value=field.value.trim();if(field.required&&!value)return ({name:'Tell us what we should call you.',email:'Enter your email address.',password:'Enter your password.',title:'Add an idea before posting.',endsAt:'Choose when voting should end.'})[field.name]||'Complete this field.';if(field.id==='create-question'&&!value)return 'Give your room a question.';if(field.type==='email'&&value&&field.validity.typeMismatch)return 'Enter a valid email address, such as you@example.com.';if(field.minLength>0&&value.length<field.minLength)return 'Use at least '+field.minLength+' characters.';if(field.maxLength>0&&value.length>field.maxLength)return 'Use no more than '+field.maxLength+' characters.';if(field.type==='datetime-local'&&value&&(!Number.isFinite(new Date(value).getTime())||new Date(value).getTime()<=Date.now()))return 'Choose a date and time in the future.';return ''}
function showFieldError(field,message){const error=document.getElementById(field.id+'-error');if(!error)return;error.textContent=message;error.hidden=!message;field.setAttribute('aria-invalid',String(Boolean(message)))}
function validateForm(form){let first;form.querySelector('.auth-status')?.replaceChildren();for(const field of form.querySelectorAll('input,textarea,select')){const message=fieldError(field);showFieldError(field,message);if(message&&!first)first=field}if(first){first.focus();return false}return true}
document.addEventListener('input',e=>{if(e.target.getAttribute('aria-invalid')==='true')showFieldError(e.target,fieldError(e.target))});
document.addEventListener('change',e=>{if(e.target.getAttribute('aria-invalid')==='true')showFieldError(e.target,fieldError(e.target))});
